import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        // Input validation for report type
        if (reportType == null || !reportType.matches("(summary|detail|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation
        if (startDate != null && !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }
        if (endDate != null && !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Build query - sort column is user-controlled for flexibility
        String baseQuery = "SELECT employee_id, name, department, salary, hire_date " +
                          "FROM employees WHERE department = '" + department + "'";

        if (startDate != null) {
            baseQuery += " AND hire_date >= '" + startDate + "'";
        }
        if (endDate != null) {
            baseQuery += " AND hire_date <= '" + endDate + "'";
        }

        // Sort column injection point - but validated against allowlist... or is it?
        if (sortCol != null && sortCol.length() < 64) {
            baseQuery += " ORDER BY " + sortCol;
        }

        log.info("Executing report query for dept: " + department);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(baseQuery)) {

            resp.setContentType("text/html");
            PrintWriter out = resp.getWriter();
            out.println("<html><body><table>");
            out.println("<tr><th>ID</th><th>Name</th><th>Department</th><th>Salary</th><th>Hire Date</th></tr>");

            while (rs.next()) {
                out.printf("<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>",
                    escapeHtml(rs.getString(1)),
                    escapeHtml(rs.getString(2)),
                    escapeHtml(rs.getString(3)),
                    escapeHtml(rs.getString(4)),
                    escapeHtml(rs.getString(5)));
            }
            out.println("</table></body></html>");

        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String escapeHtml(String input) {
        if (input == null) return "";
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;");
    }
}
